def _panel_maps(panel, z):
    from scipy.optimize import least_squares
    u = np.asarray(panel['u'], dtype=float)

    def softsign(w, q):
        return one(w / (1 + q[0] * abs(w)) + q[1] * w)

    def curvature(w, q):
        w2 = w * w
        return np.c_[one(w), w2, w2 / (1 + q[0] * w2)]

    def fit(features, target, initial, bounds, **options):

        def residual(q):
            f = features(u, q)
            return (f @ lin(f, target) - target).ravel()
        q = least_squares(residual, initial, bounds=bounds, **options).x
        return features(z, q) @ lin(features(u, q), target)
    c = fit(softsign, panel['v1'], [0.85, -0.01], ([0.02, -1], [10, 1]))
    d = fit(curvature, panel['v2'], [0.25], (0.08, 0.65), gtol=1e-13)
    return np.c_[c, d]

def _time_basis(t, trajectory):
    from scipy.optimize import least_squares

    def basis(r):
        return -np.expm1(-t[:, None] * r)

    def residual(r):
        f = basis(r)
        return (f @ lin(f, trajectory.T) - trajectory.T).ravel()
    rates = least_squares(residual, [0.4, 1.8], bounds=([0.05, 0.8], [0.8, 4])).x
    return basis(rates)

def rfit(f, v):
    r = f @ lin(f, v) - v
    for i in range(12):
        w = 1 / np.maximum(np.linalg.norm(r, axis=1), 0.001)
        r = f @ lin(f * w[:, None] ** 0.5, v * w[:, None] ** 0.5) - v
    return r
